diff --git a/middleware/basic_auth.go b/middleware/basic_auth.go
index 8a9500a..5445996 100644
--- a/middleware/basic_auth.go
+++ b/middleware/basic_auth.go
@@ -85,12 +85,16 @@ const (
 // For valid credentials it calls the next handler.
 // For missing or invalid credentials, it sends "401 - Unauthorized" response.
 func BasicAuth(fn BasicAuthValidator) echo.MiddlewareFunc {
-	return BasicAuthWithConfig(BasicAuthConfig{Validator: fn})
+	basicAuthMW, err := BasicAuthWithConfig(BasicAuthConfig{Validator: fn})
+	if err != nil {
+		panic(err)
+	}
+	return basicAuthMW
 }

 // BasicAuthWithConfig returns an BasicAuthWithConfig middleware with config.
-func BasicAuthWithConfig(config BasicAuthConfig) echo.MiddlewareFunc {
-	return toMiddlewareOrPanic(config)
+func BasicAuthWithConfig(config BasicAuthConfig) (echo.MiddlewareFunc, error) {
+	return config.ToMiddleware()
 }

 // ToMiddleware converts BasicAuthConfig to middleware or returns an error for invalid configuration
